// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *IntrastatJnlLine) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, IntrastatJnlLineTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (journal_template_name, journal_batch_name, line_no)`,
		fmt.Sprintf("%s$Intrastat_Jnl_Line$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (source_type, source_entry_no)`,
		fmt.Sprintf("%s$Intrastat_Jnl_Line$source", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index source: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (type, country_code, tariff_no, transaction_type, transport_method)`,
		fmt.Sprintf("%s$Intrastat_Jnl_Line$type_country_tariff", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type_country_tariff: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (internal_ref_no)`,
		fmt.Sprintf("%s$Intrastat_Jnl_Line$internal_ref_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index internal_ref_no: %w", err)
	}
	var keys []sift.Key
	for _, spec := range intrastatJnlLineSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, IntrastatJnlLineTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, IntrastatJnlLineTableName, keys)
}

// intrastatJnlLineSIFTSpecs are the table's keys with sum_index_fields
func intrastatJnlLineSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *IntrastatJnlLine) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, IntrastatJnlLineTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range intrastatJnlLineSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, IntrastatJnlLineTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: IntrastatJnlLineTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, IntrastatJnlLineTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

