func (t *IntrastatJnlLine) SetFilter(fieldName, filterExpr string) {
	if t.filters == nil {
		t.filters = make(map[string]*intrastatJnlLineFilterCondition)
	}
	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetFilter on unknown field %q of Intrastat_Jnl_Line\n", fieldName)
		t.filters[fieldName] = &intrastatJnlLineFilterCondition{invalidField: true}
		return
	}
	t.filters[column] = &intrastatJnlLineFilterCondition{
		fieldName:    column,
		filterExpr:   filterExpr,
		isExpression: true,
	}
}

